--region init
function ActivityMidFestivalShopDialog:InitHandler()
    ---@type ActivityMidFestivalComponent
    self._activityComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    self.events[Constants.EventNames.ActivityMidFestivalMallReq] = Events.AddListener(Constants.EventNames.ActivityMidFestivalMallReq, Bind(self, self.OnMallReqHandler))
    self.events[Constants.EventNames.ActivityMidFestivalShopLeftToggleSelect] = Events.AddListener(Constants.EventNames.ActivityMidFestivalShopLeftToggleSelect, Bind(self, self.OnLeftToggleClickHandler))
    self.events[Constants.EventNames.MidFestivalShopBuy] = Events.AddListener(Constants.EventNames.MidFestivalShopBuy, Bind(self, self.InitData))
    ---@type ActivityMidFestivalShopLeftToggleTab
    self._leftToggleScr = CfUtils.GetLuaScr(self.CommonTabToggleLeft, "Game.Activity.MidFestival.ShopDialog.ActivityMidFestivalShopLeftToggleTab")
end

---@type ActivityMidFestivalShopTool
local ActivityMidFestivalShopTool = import("Game.Activity.MidFestival.ShopDialog.ActivityMidFestivalShopTool")

function ActivityMidFestivalShopDialog:InitData()
    ActivityMidFestivalShopTool.ShopReq()
    
    ---@type ActivityMidFestivalComponent
    local activityMidFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local activityDojo = activityMidFestivalComponent:GetActivityDojo()
    if activityDojo.mallBgImage and not string.isEmpty(activityDojo.mallBgImage) then
        local mallBgImage = activityDojo.mallBgImage
        local path = CS.ParseUtils.ParsePathNameByData(mallBgImage)
        CfUtils.FillImage(self.ImgBg, path)
    end
    
end
--endregion init

--region handler
function ActivityMidFestivalShopDialog:RefreshItemByIndex(go, index)
    local luaIndex = index + 1
    local cellData = self._groupedProducts[luaIndex]
    ---@type ActivityMidFestivalShopProductCell
    local scr = CfUtils.GetLuaScr(go, "Game.Activity.MidFestival.ShopDialog.ActivityMidFestivalShopProductCell")
    scr:Refresh(cellData)
end

function ActivityMidFestivalShopDialog:OnLeftToggleClickHandler(products, isUnlock, preShopName)
    if not isUnlock then
        CfUtils.FillText(self.TxtTips, localize("购买_name_所有物品后解锁", {_name_=preShopName}))
        CfUtils.SetActive(self.ImgBgLock, true)
    else
        CfUtils.SetActive(self.ImgBgLock, false)
    end

    self._groupedProducts = checkTable(products)
    if not self.ScrollView.mLoopListView.IsListViewInit then
        self.ScrollView:InitListView(table.count(products), Bind(self, self.RefreshItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, table.count(products))
    end
    CfUtils.StopAnimation(self.Root)
    CfUtils.PlayAnimation(self.Root, "ActivityMidFestivalShopDialog_Entry")
end

function ActivityMidFestivalShopDialog:OnMallReqHandler()
    self._mallDojo = self._activityComponent:GetMallDojo()
    self._groupCount = self._mallDojo:GroupCount()
    self._productsList = self._mallDojo:GroupBy()
    self._isWaiting = false
    self:RefreshUI()
end
--endregion handler

--region private
function ActivityMidFestivalShopDialog:RefreshUI()
    self:RefreshTime()
    self:RefreshLeftTabToggle()
end

function ActivityMidFestivalShopDialog:RefreshTime()
    local time = self._mallDojo.remainingTimes
    if not isNull(self._timer) then
        CDTimerModule.GetInstance():RemoveCD(self._timer)
        self._timer = nil
    end

    self._timer = CDTimerModule.GetInstance():AddCD(1, function(_, _, delta)
        CfUtils.FillText(self.TextTime2, CfUtils.GetTimeHMS(time))
        time = time - delta
    end, CountDownTime, true, true)
end
--endregion private

--region public
--endregion public

--region get / set
function ActivityMidFestivalShopDialog:RefreshLeftTabToggle()
    if not next(checkTable(self._productsList)) then return end
    
    local viewport = self.CommonTabToggleLeft:Find("TabListView/Viewport")
    if isNotNull(viewport) then
        CfUtils.SetActive(viewport, #self._productsList > 1)
    end
    self._leftToggleScr:Refresh(self._productsList)
    --CfUtils.PlayAnimation(self.Root, "ActivityMidFestivalShopDialog_Entry")
end
--endregion get / set

return ActivityMidFestivalShopDialog